   [98]={next_id=99, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="然后，他转身走到衣柜旁，打开衣柜，看向柜里那一身陈旧却又干净的军服。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_106.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [99]={next_id=100, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="他伸手抚摸着军服，脑海中浮现起多年前的那副画面。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_106.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [100]={next_id=101, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="曾经，他和士兵们并肩作战，守护伯基索米的边疆。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_106.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [101]={next_id=102, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="曾经，他与大统领交谈甚欢，和她一起收复失地，重建伯基索米。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_106.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [102]={next_id=103, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="曾经，太多的曾经，皆因大统领而生，却也因她而化作泡影。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_106.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
